custom_css:
/*header*/
.fixed-header{
    border-top:none;
}
.fixed-header > .container{
    padding-top: 0.7em;
    padding-bottom: 1em;
}
.fixed-header ul li a{
    color:#fff !important;
}
body .fixed-header .current-menu-item .item-link:after{
    background-color:#fff !important;
    opacity:0.4 !important;
}
    
/*Content*/

.grid-image-section .vc_gitem-animated-block {
    position: relative;
    overflow: hidden;
    cursor: pointer;
    -webkit-transition: all 0.3s ease-in-out;
    transition: all 0.3s ease-in-out;
    backface-visibility: hidden;
    -webkit-backface-visibility: hidden;
}
.grid-image-section .vc_gitem-animated-block:hover .vc_gitem-zone {
     -webkit-transform: scale(1.08);
    -ms-transform: scale(1.08);
    transform: scale(1.08);
    transition: all 0.4s ease-in-out;
}
.grid-image-section .vc_gitem-animated-block .vc_gitem-zone{
    transition: all 0.5s ease-in-out;
}
.woocommerce-cart table.cart .cart-item-details a,
.row.cart-bottom h3.block-title{
    color: #1e1e1e !important;
}
body .contact-section{
    background-position: 8px !important;
    background-repeat: no-repeat !important;
    background-size: initial !important;
}
body .about-me{
    background-position: 259px !important;
    background-repeat: no-repeat !important;
    background-size: initial !important;
}
.type-product .content-product {
    margin-bottom: 70px;
}
.category-grid {
    position: relative;
    margin-bottom: 100px;
}
.letter-spac-1{
    letter-spacing:1px;
}
.letter-spac-2{
    letter-spacing:2px;
}
.letter-spac-5{
    letter-spacing:5px;
}
.initial{
    text-transform:initial !important;
}
.mpc-testimonial__signature{
    letter-spacing:2px;
}


/*Blog*/
.single-post article.blog-post,
.single-post article.post-grid {
    margin-bottom: 0px;
}
.category-grid.style-classic .categories-mask .count {
    color: #b1a7a7;
    font-size: 14px;
    letter-spacing: 2px;
}
body .category-grid .categories-mask h4{
    font-size:34px;
    text-transform: initial;
    font-weight: 400;
    margin-top: 35px;
    margin-bottom: 5px;
}

.share-post .share-title,
.comment-reply-title span{
    font-family: "Antic Didone";
    font-size:20px;
    letter-spacing:1px;
    color:#1e1b1b !important;
}
.page-numbers.current{
    background:#1e1b1b !important;
    border:none;
}
.articles-pagination a{
   border:none !important; 
}
.form-submit input[type=submit]:hover{
    color:#706565;
    border-bottom-color:#706565;
}
.single-post input[type="text"]::-webkit-input-placeholder,
.single-post input[type="email"]::-webkit-input-placeholder,
.single-post textarea::-webkit-input-placeholder{
    color: #706565;
    font-family: "Antic Didone";
    letter-spacing:1px;
    font-size:16px;
}
.single-tags a {
    color: #1e1b1b;
    font-family: "Antic Didone";
    letter-spacing: 1px;
}
.share-post .menu-social-icons {
    margin-top: 6px;
}
.single-post .single-post-large .post-heading{
    text-align:center;
}
.global-post-template-large .single-post-large-wrapper .post-heading h2{
    text-transform: initial;
    font-size: 40px;
    margin-bottom: 22px;
}
.single-post .meta-post {
    font-size: 18px !important;
}
.form-submit input[type=submit]{
    line-height: 14px;
    font-size: 20px;
    color: #1e1b1b;
    background: transparent !important;
    font-family: Raleway;
    border: none;
    font-weight: 400 !important;
    height: 20px;
    border-bottom: 1px solid #1e1b1b !important;
    padding: 0;
    text-transform: initial;
    margin-bottom:60px;
}
.articles-pagination a:hover,
.articles-pagination span:hover {
    background:#1e1b1b !important;
}
.articles-pagination a,
.articles-pagination span {
    font-size:15px;
}
.meta-post-timeline .time-day{
    font-size:30px !important;
    margin-top:5px !important;
}
.meta-post-timeline .time-mon{
    font-size:16px !important;
    margin-top:-5px !important;
}
.meta-post-timeline{
    letter-spacing: 2px;
    font-family: "Antic Didone";
}
.content-article{
    padding:0 30px;
}
.post-heading {
    margin-bottom: 1.3em;
}
.meta-post{
    font-size:15px !important;
}
.read-more{
    font-size:18px;
    font-family: "Antic Didone";
    color:#1e1b1b !important;
    margin-top:20px !important;
}
body .post-heading h2{
    margin-bottom:10px;
    margin-top: 50px;
}
body .post-heading h2 a{
    color:#1e1b1b !important;
    font-size:24px;
    font-family: "Antic Didone";
    font-weight: 400;
    letter-spacing:1px;
}

/*Shop*/
.quick-view-popup .product-name {
    font-size: 2.1rem;
}
.pagination-cubic .page-numbers{
    min-width: 37px;
    text-align:center;
}
.single-product .product-information-inner{
    padding-top:30px;
}
.single-product .price .woocommerce-Price-amount{
    font-size: 36px;
    font-weight: 400;
    font-family: "Antic Didone";
}
.archive .after-shop-loop{
    display:none !important;
}
.product-information .title{
    font-size: 26px;
    font-weight: 400;
    color: #1e1b1b;
    text-transform: inherit;
}
.product-information .products-page-cats a{
    color: #b1a7a7;
    font-weight: 400;
    font-size: 12px;
    letter-spacing: 2px;
}
.compare.button{
    display:none;
}
.qty-span,
body .product-share .share-title{
    font-size: 20px;
    display: inline-table;
    text-transform: capitalize;
    color: #1e1b1b;
    margin-right: 20px;
    font-family: "Antic Didone";
    font-weight: 400;
}
.product-share ul li a {
    color: #b1a7a7;
}
body .single_add_to_cart_button:hover{
    background-color: transparent;
    color: #706565;
    border-color: #fff;
    border-bottom: 1px solid #706565;
}
.single_add_to_cart_button{
    letter-spacing:1px;
    background-color: transparent;
    border-width: 1px;
    border-color: #fff;
    color: #1e1b1b;
    font-family: "Antic Didone";
    text-transform: initial;
    font-weight: 400;
    font-size: 20px !important;
    min-width: auto;
    border-bottom: 1px solid #1e1b1b;
    padding: 0;
    height: 2.4rem;
}
.post-categories{
    display:none !important;
}
.tabs .tab-title {
    letter-spacing:1px;
    color:#1e1b1b !important;
    font-family: "Antic Didone";
    font-weight: 400;
    text-transform: capitalize;
    font-size: 18px;
}
body .shopping-container .cart-bag .badge-number {
    background:#706565 !important;
}
.tabs .tab-content {
    padding: 0 0 30px;
}
.single-product .tab-content-scroll h2{
    text-transform: initial !important;
}
.filter-wrap {
    margin-bottom: 50px;
}
.products-per-page span{
    font-family: "Antic Didone";
    text-transform: inherit !important;
    font-size:16px;
    letter-spacing:1px;
    font-weight:400 !important;
    color:#1e1b1b !important;
}
span.price{
    font-weight:400 !important;
}
span.price span{
    font-size: 22px;
    font-family: "Antic Didone";
    font-weight: 400;
    letter-spacing: 1px;
    color: #1e1b1b !important;
}
.star-rating span:before {
    color: #ffca2a !important;
}
.content-product .products-page-cats,
.content-product .products-page-brands {
    margin-bottom: .7em;
}
.content-product .products-page-cats a,
.content-product .products-page-brands a{
    font-size: 12px;
    font-family: Raleway;
    color: #b1a7a7;
    font-weight: 300;
    text-transform: uppercase;
    letter-spacing: 2px;
}
body .content-product .product-title a{
    color: #1e1b1b;
    font-size: 26px;
}

/*footer*/
footer.footer .menu-element.horizontal li:last-child {
    padding-right: 0 !important;
}
footer.footer .et-follow-buttons.buttons-size-normal a {
    font-size: 18px;
    padding: 0 10px;
    color: #706565 !important;
}
footer.footer .et-follow-buttons.buttons-size-normal a:hover {
    color: #b1a7a7 !important;
}
footer.footer .menu-element.horizontal li {
    padding: 0 70px 0 0;
}
footer.footer ul li a{
    font-size:16px;
    font-family: "Antic Didone";
    letter-spacing:2px;
}
footer.footer .menu{
    margin-bottom:-6px;
}


@media screen and (min-width: 481px) {
 .mpc-carousel-image .slick-slide.mpc-carousel__item-wrapper {
    margin-bottom: 0 !important;
    padding: 0 15px;
 }
}

@media screen and (max-width: 480px) {
    .fixed-header > .container {
      padding-top: 0.2em;
      padding-bottom: 0.5em;
    }
    footer.footer *{
       text-align:center !important;
    }
    footer.footer .menu-element.horizontal li {
       padding:3px 20px;
    }
    footer.footer .menu{
        margin-bottom:30px;
        margin-top:30px;
    }
    body .contact-us-information{
        background-image: none !important;
        padding-top: 25px !important;
        padding-bottom: 25px !important;
    }
    .price__section *{
        text-align:left !important;
    }
    .price__section > .vc_column-inner{
        padding-top:0px !important;
    }
    .responsive-none{
        display:none;
    }
    .products-grid .product-category {
       width: 100% !important;
       margin-bottom: 70px !important;
       padding-left: 15px !important;
       padding-right: 15px !important;
    }
    body .content-product .product-title a {
       font-size: 20px;
    }
    .single-product .mpc-overlay.mpc-overlay--first{
        display:none;
    }
    .single-product .price .woocommerce-Price-amount {
        font-size: 26px;
    }
    body .mpc-divider-wrap + h2,
    .center-section{
        margin-bottom:45px !important;
    }
    .contacts__section .mpc-icon.mpc-transition{
        display:none;
    }
    .home .mpc-tabs__nav.mpc-align--center ul{
        margin-bottom:-17px;
    }
    .quick-view-popup .add_to_cart_button {
       min-width: 100px;
     }
    
}
